import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
import '../app_state.dart';
import '../models/hotel.dart';
class BookingScreen extends StatefulWidget { const BookingScreen({required this.hotel,required this.appState,required this.nights,super.key}); final Hotel hotel; final AppState appState; final int nights; @override State<BookingScreen> createState()=>_BookingScreenState(); }
class _BookingScreenState extends State<BookingScreen> {
  int _guests=2; bool _saved=false; bool _changed=false;
  Future<void> _pickGuests() async { final result=await context.push<int>('/hotels/${widget.hotel.id}/book/guests?value=$_guests'); if(!mounted)return; if(result!=null)setState(()=>_guests=result); }
  void _confirm(){setState(()=>_saved=true);widget.appState.addTrip(widget.hotel.id);ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Бронювання збережено')));}
  @override Widget build(BuildContext context)=>PopScope(canPop:!_changed,onPopInvokedWithResult:(didPop,result)async{if(didPop)return;final leave=await showDialog<bool>(context:context,builder:(context)=>AlertDialog(title:const Text('Вийти без збереження?'),content:const Text('Введені дані буде втрачено.'),actions:[TextButton(onPressed:()=>context.pop(false),child:const Text('Залишитися')),FilledButton(onPressed:()=>context.pop(true),child:const Text('Вийти'))]));if(leave==true&&context.mounted)context.pop();},child:Scaffold(appBar:AppBar(title:const Text('Бронювання')),body:ListView(padding:const EdgeInsets.all(20),children:[Text(widget.hotel.name,style:Theme.of(context).textTheme.headlineSmall),Text('${widget.nights} ночі · ${widget.hotel.price*widget.nights} грн'),const SizedBox(height:20),Card(child:ListTile(leading:const Icon(Icons.people),title:Text('Гості: $_guests'),trailing:TextButton(onPressed:_pickGuests,child:const Text('Змінити')))),TextField(decoration:const InputDecoration(labelText:'Ім’я гостя',border:OutlineInputBorder()),onChanged:(_)=>setState(()=>_changed=true)),const SizedBox(height:16),CheckboxListTile(value:_saved,onChanged:(_)=>setState(()=>_changed=true),title:const Text('Погоджуюсь з умовами бронювання')),const SizedBox(height:16),FilledButton(onPressed:_confirm,child:const Text('Підтвердити бронювання'))])));
}
